// Verus program: determine the winner by absolute difference.
//
// Rule:
// - If |x - y| > 1  => "Alice"
// - Otherwise       => "Brown"

use vstd::prelude::*;

verus! {

spec fn abs_diff_i8(x: i8, y: i8) -> int {
    // Work in mathematical ints to avoid overflow issues.
    if x as int >= y as int { x as int - y as int } else { y as int - x as int }
}

fn determine_winner(x: i8, y: i8) -> (winner: &'static str)
    requires
        // Problem states inputs are nonnegative.
        x >= 0,
        y >= 0,
    ensures
        // Output is always one of the two required strings.
        winner == "Alice" || winner == "Brown",
        // Correctness characterization.
        (winner == "Alice") <==> (abs_diff_i8(x, y) > 1),
        (winner == "Brown") <==> (abs_diff_i8(x, y) <= 1),
{
    let d: i8 = if x >= y { x - y } else { y - x };

    if d > 1 {
        "Alice"
    } else {
        "Brown"
    }
}

} // verus!